@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

fl =(a)=>{
t = String(Math.round(new Date()));
return `https://api.ieasou.com/api/bookapp/searchdzh.m?word=${a}&type=2&page_id={{page}}&count=20&sort_type=0&subclass=0&datasource=0&showj=1&wc=0&catalog=0&bookStatus=0&cid=eef_easou_book&vm=5.8.5&os=android&udid=3d3ec742930b635fc4c61f0575dbc4d2939edbe2&appverion=508500&ch=blf1298_10928_001&session_id=C757AFA560J0A6092827V469973C4D670288F658484753375777AE72183BFF560C&dzh=1&scp=0&appid=10001&utype=0&rtype=2&pushid=da97011e945dfb4c74bbfc98543c7c7a&ptype=5&gender=1&userInitPay=3&birt=1706674841000&instime=${t}&instId=${t}&chType=6&bidType=100&recSw=1&appType=0&pr=0.09&tm=0&ac=999&snk={{java.md5Encode('ac=999&appType=0&appid=10001&appverion=508500&bidType=100&birt=1706674841000&bookStatus=0&catalog=0&ch=blf1298_10928_001&chType=6&cid=eef_easou_book&count=20&datasource=0&dzh=1&gender=1&instId='+${t}+'&instime='+${t}+'&os=android&page_id='+page+'&pr=0.09&ptype=5&pushid=da97011e945dfb4c74bbfc98543c7c7a&recSw=1&rtype=2&scp=0&session_id=C757AFA560J0A6092827V469973C4D670288F658484753375777AE72183BFF560C&showj=1&sort_type=0&subclass=0&tm=0&type=2&udid=3d3ec742930b635fc4c61f0575dbc4d2939edbe2&userInitPay=3&utype=0&vm=5.8.5&wc=0&word=${a}&key=EaSoU0517+PuBlIsHkEy-JRKKOWTUNZCNTWY-').toUpperCase()}}`;
}


[["男生♂分类",["现代都市","玄幻奇幻","武侠仙侠","科幻小说","历史军事","灵异悬疑","游戏竞技","宅小说","重生致富","系统文","奶爸","文娱"]],
["女生♀分类",["现代言情","古代言情","幻想言情","浪漫青春","种田","总裁","马甲文","轻小说"]],
["出版©️分类",["短篇","经典名著","其他出版","现代文学"]]].map([tit,list]=>{
	push(tit, null, 1, 1);
	list.map((title,index)=>{
	if(index+1 <= list.length - list.length%3){
			push(title,fl(title), 1, 0.25);}
			else{ push(title,fl(title), 0, 0.29);}
		});
})

JSON.stringify(sort);

